xml.Script:
        clBlue   := '0000C8';
        clGreen  := '009600';
        clRed    := 'C80000';
        clPurple := '800080';
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';
        clOrange := 'FF6000';

        R := 0.62;

        sAngle := PI * 2 / 5;
        for i := 0 to 4 do begin
            ax[i] :=-sin(sAngle * i);
            ay[i] :=-cos(sAngle * i);
            x[i] :=-R * ax[i];
            y[i] :=-R * ay[i];
        end;

        D1 := (R * cos(Pi/5) * 6 + R * cos(3*Pi/5) * 1) / 7;
        D2 := (R * cos(Pi/5) * 5 + R * cos(3*Pi/5) * 2) / 7;
        D3 := (R * cos(Pi/5) * 4 + R * cos(3*Pi/5) * 3) / 7;

        H := R * sin(Pi / 5) / 7 * 4;
        DH := H / 2;
